public static List<JSONObject> createWhiteLightConfigPidList(WhiteLightConfigInfo whiteLightConfigInfo) {
    LogUtils.d("<literal omitted>", "<literal omitted>" + whiteLightConfigInfo + "<literal omitted>");
    JSONObject jSONObject = null;
    if (whiteLightConfigInfo == null) {
        return null;
    }
    ArrayList arrayList = new ArrayList();
    LightTimerInfoJsonParse lightTimerInfoJsonParse = new LightTimerInfoJsonParse();
    lightTimerInfoJsonParse.setDefaultAction(whiteLightConfigInfo.getDefaultAction());
    lightTimerInfoJsonParse.setCapability(whiteLightConfigInfo.getCapability());
    lightTimerInfoJsonParse.setTotal(whiteLightConfigInfo.getTotal());
    if (whiteLightConfigInfo.getActionData() != null && whiteLightConfigInfo.getActionData().size() > 0) {
        ArrayList arrayList2 = new ArrayList();
        for (WhiteLightConfigInfo.ActionData actionData : whiteLightConfigInfo.getActionData()) {
            LightTimerInfoJsonParse.TimeSchedule timeSchedule = new LightTimerInfoJsonParse.TimeSchedule();
            int i = 1;
            if (actionData.getAction() != 1) {
                i = 0;
            }
            timeSchedule.setEnable(i);
            timeSchedule.setS_time(actionData.getStartTime() + "<literal omitted>");
            timeSchedule.setE_time(actionData.getEndTime() + "<literal omitted>");
            arrayList2.add(timeSchedule);
        }
        lightTimerInfoJsonParse.setTime_schedule(arrayList2);
    }
    try {
        jSONObject = new JSONObject(new Gson().toJson(lightTimerInfoJsonParse));
    } catch (JSONException e) {
        e.printStackTrace();
    }
    arrayList.add(createJSONObjectValueJsonObj(Protocol.DPID_LIGHT_SCHEDULE, jSONObject));
    LogUtils.d("<literal omitted>", "<literal omitted>" + arrayList);
    return arrayList;
}
